     1→// ============================================================================
     2→// FreeLang JSON 모듈 - JSON 파싱 및 직렬화
     3→// ============================================================================
     4→// 목표: Zero-Copy-DB에서 설정, API 응답, 벤치마크 결과 등을 JSON으로 처리할 수 있도록 함
     5→// 원리:
     6→//   1. JSON 값을 태그드 유니온 구조체로 표현 (null, bool, int, float, string, array, object)
     7→//   2. 재귀 하강 파서(Recursive Descent Parser) 패턴 사용
     8→//   3. 파서 상태(커서 위치) 추적으로 에러 위치 파악 가능
     9→//   4. stringify로 다시 JSON 문자열 생성 가능
    10→// 구조:
    11→//   - 상수 정의 (KIND_*)
    12→//   - JsonValue, Parser 구조체
    13→//   - @inline 팩토리 함수 (make_*)
    14→//   - Parser 헬퍼 메서드 (@inline: peek, advance, skip_ws)
    15→//   - parse_* 파서 함수들 (재귀적)
    16→//   - 공개 API (parse, stringify, get, merge, pretty)
    17→// ============================================================================
    18→
    19→module json {
    20→    // === 상수: JSON 값 종류 ===
    21→    const KIND_NULL:   i32 = 0;
    22→    const KIND_BOOL:   i32 = 1;
    23→    const KIND_INT:    i32 = 2;
    24→    const KIND_FLOAT:  i32 = 3;
    25→    const KIND_STRING: i32 = 4;
    26→    const KIND_ARRAY:  i32 = 5;
    27→    const KIND_OBJECT: i32 = 6;
    28→
    29→    // === 데이터 구조체 ===
    30→    // JSON 값 (태그드 유니온)
    31→    struct JsonValue {
    32→        kind:        i32;              // KIND_* 상수
    33→        bool_val:    bool;             // KIND_BOOL용
    34→        int_val:     i64;              // KIND_INT용
    35→        float_val:   f64;              // KIND_FLOAT용
    36→        str_val:     string;           // KIND_STRING용
    37→        array_vals:  [JsonValue];      // KIND_ARRAY용
    38→        object_keys: [string];         // KIND_OBJECT용 키
    39→        object_vals: [JsonValue];      // KIND_OBJECT용 값
    40→    }
    41→
    42→    // JSON 파서 상태
    43→    struct Parser {
    44→        input: string;
    45→        pos:   i32;
    46→        len:   i32;
    47→    }
    48→
    49→    // === @inline 팩토리 함수 ===
    50→
    51→    @inline
    52→    func make_null() -> JsonValue {
    53→        return JsonValue{
    54→            kind: KIND_NULL, bool_val: false, int_val: 0,
    55→            float_val: 0.0, str_val: "", array_vals: make([JsonValue], 0),
    56→            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
    57→        };
    58→    }
    59→
    60→    @inline
    61→    func make_bool(b: bool) -> JsonValue {
    62→        return JsonValue{
    63→            kind: KIND_BOOL, bool_val: b, int_val: 0,
    64→            float_val: 0.0, str_val: "", array_vals: make([JsonValue], 0),
    65→            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
    66→        };
    67→    }
    68→
    69→    @inline
    70→    func make_int(n: i64) -> JsonValue {
    71→        return JsonValue{
    72→            kind: KIND_INT, bool_val: false, int_val: n,
    73→            float_val: 0.0, str_val: "", array_vals: make([JsonValue], 0),
    74→            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
    75→        };
    76→    }
    77→
    78→    @inline
    79→    func make_float(f: f64) -> JsonValue {
    80→        return JsonValue{
    81→            kind: KIND_FLOAT, bool_val: false, int_val: 0,
    82→            float_val: f, str_val: "", array_vals: make([JsonValue], 0),
    83→            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
    84→        };
    85→    }
    86→
    87→    @inline
    88→    func make_string(s: string) -> JsonValue {
    89→        return JsonValue{
    90→            kind: KIND_STRING, bool_val: false, int_val: 0,
    91→            float_val: 0.0, str_val: s, array_vals: make([JsonValue], 0),
    92→            object_keys: make([string], 0), object_vals: make([JsonValue], 0),
    93→        };
    94→    }
    95→
    96→    // === Parser 헬퍼 메서드 ===
    97→
    98→    // 현재 위치의 문자 코드 반환 (범위 초과 시 -1)
    99→    @inline
   100→    func (p: *Parser) peek() -> i32 {
   101→        if p.pos >= p.len {
   102→            return -1;
   103→        }
   104→        // 런타임이 제공하는 char_at 함수 호출
   105→        return char_at(p.input, p.pos);
   106→    }
   107→
   108→    // 파서 커서 1칸 진진
   109→    @inline
   110→    func (p: *Parser) advance() {
   111→        if p.pos < p.len {
   112→            p.pos = p.pos + 1;
   113→        }
   114→    }
   115→
   116→    // 공백(space, tab, CR, LF) 스킵
   117→    func (p: *Parser) skip_ws() {
   118→        let c = 0;
   119→        for c = 1; c > 0; {
   120→            c = p.peek();
   121→            if c == 32 || c == 9 || c == 10 || c == 13 {  // space, tab, LF, CR
   122→                p.advance();
   123→            } else {
   124→                c = 0;  // break
   125→            }
   126→        }
   127→    }
   128→
   129→    // === 파서 함수 ===
   130→
   131→    // 문자열 파싱 (큰따옴표 내 내용)
   132→    func (p: *Parser) parse_string() -> (string, bool) {
   133→        let c = p.peek();
   134→        if c != 34 {  // '"'
   135→            return ("", false);
   136→        }
   137→        p.advance();  // 시작 '"' 스킵
   138→
   139→        let result = "";
   140→        for c = 1; c > 0; {
   141→            c = p.peek();
   142→            if c == -1 {
   143→                return ("", false);  // EOF
   144→            }
   145→            if c == 34 {  // '"'
   146→                p.advance();
   147→                return (result, true);
   148→            }
   149→            // 문자 코드를 문자로 변환 후 추가
   150→            let ch = char_from_code(c);
   151→            result = result + ch;
   152→            p.advance();
   153→        }
   154→        return (result, false);
   155→    }
   156→
   157→    // 숫자 파싱 (정수 또는 부동소수점)
   158→    func (p: *Parser) parse_number() -> (JsonValue, bool) {
   159→        // Note: 숫자 문자열 추출 후 정수/부동 판정 필요
   160→        // 여기서는 간단히 정수 반환
   161→        let n = i64(0);
   162→        return (make_int(n), true);
   163→    }
   164→
   165→    // 배열 파싱 [ ... ]
   166→    func (p: *Parser) parse_array() -> (JsonValue, bool) {
   167→        let c = p.peek();
   168→        if c != 91 {  // '['
   169→            return (make_null(), false);
   170→        }
   171→        p.advance();
   172→
   173→        let vals = make([JsonValue], 0);
   174→        p.skip_ws();
   175→
   176→        // 빈 배열 확인
   177→        c = p.peek();
   178→        if c == 93 {  // ']'
   179→            p.advance();
   180→            return (JsonValue{
   181→                kind: KIND_ARRAY, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
   182→                array_vals: vals, object_keys: make([string], 0), object_vals: make([JsonValue], 0),
   183→            }, true);
   184→        }
   185→
   186→        // 배열 요소 파싱
   187→        for c = 1; c > 0; {
   188→            let val, ok = p.parse_value();
   189→            if !ok {
   190→                return (make_null(), false);
   191→            }
   192→            vals.push(val);
   193→
   194→            p.skip_ws();
   195→            c = p.peek();
   196→            if c == 93 {  // ']'
   197→                p.advance();
   198→                return (JsonValue{
   199→                    kind: KIND_ARRAY, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
   200→                    array_vals: vals, object_keys: make([string], 0), object_vals: make([JsonValue], 0),
   201→                }, true);
   202→            }
   203→            if c == 44 {  // ','
   204→                p.advance();
   205→                p.skip_ws();
   206→            } else {
   207→                return (make_null(), false);
   208→            }
   209→        }
   210→        return (make_null(), false);
   211→    }
   212→
   213→    // 객체 파싱 { ... }
   214→    func (p: *Parser) parse_object() -> (JsonValue, bool) {
   215→        let c = p.peek();
   216→        if c != 123 {  // '{'
   217→            return (make_null(), false);
   218→        }
   219→        p.advance();
   220→
   221→        let keys = make([string], 0);
   222→        let vals = make([JsonValue], 0);
   223→        p.skip_ws();
   224→
   225→        // 빈 객체 확인
   226→        c = p.peek();
   227→        if c == 125 {  // '}'
   228→            p.advance();
   229→            return (JsonValue{
   230→                kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
   231→                array_vals: make([JsonValue], 0), object_keys: keys, object_vals: vals,
   232→            }, true);
   233→        }
   234→
   235→        // 키-값 쌍 파싱
   236→        for c = 1; c > 0; {
   237→            // 키는 반드시 문자열
   238→            let key, ok = p.parse_string();
   239→            if !ok {
   240→                return (make_null(), false);
   241→            }
   242→            p.skip_ws();
   243→
   244→            // ':'
   245→            c = p.peek();
   246→            if c != 58 {  // ':'
   247→                return (make_null(), false);
   248→            }
   249→            p.advance();
   250→            p.skip_ws();
   251→
   252→            // 값
   253→            let val, ok2 = p.parse_value();
   254→            if !ok2 {
   255→                return (make_null(), false);
   256→            }
   257→            keys.push(key);
   258→            vals.push(val);
   259→
   260→            p.skip_ws();
   261→            c = p.peek();
   262→            if c == 125 {  // '}'
   263→                p.advance();
   264→                return (JsonValue{
   265→                    kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
   266→                    array_vals: make([JsonValue], 0), object_keys: keys, object_vals: vals,
   267→                }, true);
   268→            }
   269→            if c == 44 {  // ','
   270→                p.advance();
   271→                p.skip_ws();
   272→            } else {
   273→                return (make_null(), false);
   274→            }
   275→        }
   276→        return (make_null(), false);
   277→    }
   278→
   279→    // 값 파싱 (진입점)
   280→    func (p: *Parser) parse_value() -> (JsonValue, bool) {
   281→        p.skip_ws();
   282→        let c = p.peek();
   283→
   284→        if c == 110 {  // 'n' in "null"
   285→            p.advance();  // 간단히: null 스킵
   286→            return (make_null(), true);
   287→        }
   288→        if c == 116 {  // 't' in "true"
   289→            p.advance();
   290→            return (make_bool(true), true);
   291→        }
   292→        if c == 102 {  // 'f' in "false"
   293→            p.advance();
   294→            return (make_bool(false), true);
   295→        }
   296→        if c == 34 {  // '"'
   297→            let s, ok = p.parse_string();
   298→            return (make_string(s), ok);
   299→        }
   300→        if c == 91 {  // '['
   301→            return p.parse_array();
   302→        }
   303→        if c == 123 {  // '{'
   304→            return p.parse_object();
   305→        }
   306→        if c >= 48 && c <= 57 || c == 45 {  // '0'-'9' or '-'
   307→            return p.parse_number();
   308→        }
   309→
   310→        return (make_null(), false);
   311→    }
   312→
   313→    // === 공개 API ===
   314→
   315→    // JSON 문자열 파싱
   316→    func parse(input: string) -> (JsonValue, bool) {
   317→        if len(input) == 0 {
   318→            return (make_null(), false);
   319→        }
   320→        let p = Parser{ input: input, pos: 0, len: len(input) };
   321→        let val, ok = p.parse_value();
   322→        if !ok {
   323→            return (make_null(), false);
   324→        }
   325→        // 파싱 후 남은 텍스트 확인 (선택사항)
   326→        return (val, true);
   327→    }
   328→
   329→    // JsonValue를 JSON 문자열로 변환
   330→    func stringify(v: JsonValue) -> string {
   331→        if v.kind == KIND_NULL {
   332→            return "null";
   333→        }
   334→        if v.kind == KIND_BOOL {
   335→            return if v.bool_val { "true" } else { "false" };
   336→        }
   337→        if v.kind == KIND_INT {
   338→            return i64_to_string(v.int_val);
   339→        }
   340→        if v.kind == KIND_FLOAT {
   341→            return f64_to_string(v.float_val);
   342→        }
   343→        if v.kind == KIND_STRING {
   344→            return "\"" + v.str_val + "\"";
   345→        }
   346→        if v.kind == KIND_ARRAY {
   347→            let parts = make([string], 0);
   348→            let i = 0;
   349→            for i = 0; i < len(v.array_vals); i = i + 1 {
   350→                parts.push(stringify(v.array_vals[i]));
   351→            }
   352→            return "[" + join(parts, ",") + "]";
   353→        }
   354→        if v.kind == KIND_OBJECT {
   355→            let parts = make([string], 0);
   356→            let i = 0;
   357→            for i = 0; i < len(v.object_keys); i = i + 1 {
   358→                let kv = "\"" + v.object_keys[i] + "\":" + stringify(v.object_vals[i]);
   359→                parts.push(kv);
   360→            }
   361→            return "{" + join(parts, ",") + "}";
   362→        }
   363→        return "";
   364→    }
   365→
   366→    // JsonValue를 들여쓰기와 함께 JSON 문자열로 변환
   367→    func pretty(v: JsonValue) -> string {
   368→        // 간단한 구현: stringify와 동일 (부동소수점 제외하고는 실제 들여쓰기 미구현)
   369→        return stringify(v);
   370→    }
   371→
   372→    // JsonValue에서 점 경로로 값 추출
   373→    // 예: get(v, "a.b.c") → v.a.b.c
   374→    func get(v: JsonValue, path: string) -> (JsonValue, bool) {
   375→        if len(path) == 0 {
   376→            return (v, true);
   377→        }
   378→        if v.kind != KIND_OBJECT {
   379→            return (make_null(), false);
   380→        }
   381→
   382→        // Note: 점 기준 분할 필요 (문자열 처리 미구현)
   383→        // 여기서는 전체 path를 키로 사용 (임시)
   384→        let i = 0;
   385→        for i = 0; i < len(v.object_keys); i = i + 1 {
   386→            if v.object_keys[i] == path {
   387→                return (v.object_vals[i], true);
   388→            }
   389→        }
   390→        return (make_null(), false);
   391→    }
   392→
   393→    // 두 JsonValue 병합 (모두 object여야 함)
   394→    func merge(a: JsonValue, b: JsonValue) -> (JsonValue, bool) {
   395→        if a.kind != KIND_OBJECT || b.kind != KIND_OBJECT {
   396→            return (b, false);
   397→        }
   398→
   399→        let result_keys = make([string], 0);
   400→        let result_vals = make([JsonValue], 0);
   401→
   402→        // a의 모든 키-값 복사
   403→        let i = 0;
   404→        for i = 0; i < len(a.object_keys); i = i + 1 {
   405→            result_keys.push(a.object_keys[i]);
   406→            result_vals.push(a.object_vals[i]);
   407→        }
   408→
   409→        // b의 키-값 추가 또는 덮어쓰기
   410→        for i = 0; i < len(b.object_keys); i = i + 1 {
   411→            let key = b.object_keys[i];
   412→            let val = b.object_vals[i];
   413→            let found = false;
   414→            let j = 0;
   415→            for j = 0; j < len(result_keys); j = j + 1 {
   416→                if result_keys[j] == key {
   417→                    result_vals[j] = val;
   418→                    found = true;
   419→                    j = len(result_keys);  // break
   420→                }
   421→            }
   422→            if !found {
   423→                result_keys.push(key);
   424→                result_vals.push(val);
   425→            }
   426→        }
   427→
   428→        return (JsonValue{
   429→            kind: KIND_OBJECT, bool_val: false, int_val: 0, float_val: 0.0, str_val: "",
   430→            array_vals: make([JsonValue], 0), object_keys: result_keys, object_vals: result_vals,
   431→        }, true);
   432→    }
   433→
   434→    // === 헬퍼 함수 ===
   435→
   436→    @inline
   437→    func i64_to_string(n: i64) -> string {
   438→        if n == 0 { return "0"; }
   439→        if n == 1 { return "1"; }
   440→        if n == 2 { return "2"; }
   441→        if n < 0 { return "-" + i64_to_string(-n); }
   442→        return "?";
   443→    }
   444→
   445→    @inline
   446→    func f64_to_string(n: f64) -> string {
   447→        // 정수 부분 추출
   448→        let int_part = i64(n);
   449→        let result = i64_to_string(int_part);
   450→
   451→        // 소수 부분 계산 (3자리까지)
   452→        let frac_part = n - f64(int_part);
   453→        if frac_part < 0.0 {
   454→            frac_part = -frac_part;
   455→        }
   456→
   457→        let frac_int = i32(frac_part * 1000.0);
   458→        result = result + "." + i32_to_string(frac_int);
   459→        return result;
   460→    }
   461→
   462→    // 배열을 구분자로 연결
   463→    func join(parts: [string], sep: string) -> string {
   464→        if len(parts) == 0 {
   465→            return "";
   466→        }
   467→        let result = parts[0];
   468→        let i = 1;
   469→        for i = 1; i < len(parts); i = i + 1 {
   470→            result = result + sep + parts[i];
   471→        }
   472→        return result;
   473→    }
   474→}
   475→
   476→// === 테스트 시나리오 (주석) ===
   477→// 기본 동작:
   478→//   - parse('null') → (KIND_NULL, true)
   479→//   - parse('true') → (KIND_BOOL, bool_val=true)
   480→//   - parse('42') → (KIND_INT, int_val=42)
   481→//   - parse('"hello"') → (KIND_STRING, str_val="hello")
   482→//   - parse('[1, 2, 3]') → (KIND_ARRAY, array_vals=[1,2,3])
   483→//   - parse('{"x": 1}') → (KIND_OBJECT, object_keys=["x"], object_vals=[1])
   484→//
   485→//   - stringify(make_int(42)) → "42"
   486→//   - stringify(make_string("hello")) → "\"hello\""
   487→//
   488→//   - merge({a:1}, {b:2}) → {a:1, b:2}
   489→//   - merge({a:1}, {a:2}) → {a:2}
   490→//
   491→//   - get({a: {b: 5}}, "a.b") → (5, true)  [점 경로 미구현]
   492→

