   353→// === 테스트 시나리오 (주석) ===
   354→// 기본 동작:
   355→//   - chan_new(10) → Channel{ capacity: 10, count: 0, state: CHAN_OPEN }
   356→//   - ch.chan_send(42) → true
   357→//   - ch.chan_recv() → (42, true)
