     2→// FreeLang I/O 모듈 - 파일 및 디렉토리 시스템 인터페이스
     3→// ============================================================================
     4→// 목표: Zero-Copy-DB에서 설정 파일, 벤치마크 결과, 로그 등을 읽고 쓸 수 있도록 함
     5→// 원리:
     6→//   1. 모든 파일 I/O 함수는 (value, bool) 다중 반환으로 성공/실패 구분
     7→//   2. sys_* 브리지 함수를 통해 런타임이 실제 OS 시스템 콜 오버라이드 가능
     8→//   3. 에러 코드로 근본 원인 추적 가능
     9→// 구조:
    10→//   - 에러 상수 정의
    11→//   - 데이터 구조체 (FileResult, DirEntry)
    12→//   - 경로 조작 헬퍼 (join_path, basename, dirname)
    13→//   - 내부 헬퍼 (@inline split_lines)
    14→//   - 시스템 브리지 함수 (sys_*)
    15→//   - 공개 API (read_file, write_file, append_file, file_exists, read_lines, list_dir)
    16→// ============================================================================
    17→
    18→module io {
    19→    // === 에러 코드 ===
    20→    const ERR_OK:         i32 = 0;
    21→    const ERR_NOT_FOUND:  i32 = 1;
    22→    const ERR_PERMISSION: i32 = 2;
    23→    const ERR_IO:         i32 = 3;
    24→    const ERR_INVALID:    i32 = 4;
    25→
    26→    // === 데이터 구조체 ===
    27→    // 파일 작업 결과 컨텍스트
    28→    struct FileResult {
    29→        success:          bool;
    30→        error_code:       i32;
    31→        bytes_processed:  u64;
    32→    }
    33→
    34→    // 디렉토리 항목 (list_dir 반환값)
    35→    struct DirEntry {
    36→        name:   string;
    37→        is_dir: bool;
    38→        size:   u64;
    39→    }
    40→
    41→    // === 내부 헬퍼 함수 ===
    42→    // '\n'을 기준으로 문자열을 라인으로 분할
    43→    @inline
    44→    func split_lines(content: string) -> [string] {
    45→        let lines = make([string], 0);
    46→        let current = "";
    47→        let i = 0;
    48→        let len_val = len(content);
    49→
    50→        for i = 0; i < len_val; i = i + 1 {
    51→            let ch_code = char_at(content, i);
    52→            if ch_code == 10 {  // '\n'
    53→                lines.push(current);
    54→                current = "";
    55→            } else if ch_code == 13 {  // '\r' (Windows)
    56→                // Skip carriage return
    57→            } else {
    58→                let ch = char_from_code(ch_code);
    59→                current = current + ch;
    60→            }
    61→        }
    62→        // 마지막 줄 추가 (개행 없으면)
    63→        if len(current) > 0 {
    64→            lines.push(current);
    65→        }
    66→        return lines;
    67→    }
    68→
    69→    // === 시스템 브리지 함수 (런타임 오버라이드 지점) ===
    70→    // 이 함수들은 런타임이 실제 OS 시스템 콜로 대체해야 함
    71→
    72→    // Linux: open(path, O_RDONLY), read(fd, buf, size), close(fd)
    73→    func sys_read_file(path: string) -> (string, i32) {
    74→        // 모의 구현: 파일을 읽지 못함
    75→        // 실제 구현은 런타임이 제공해야 함
    76→        if len(path) == 0 {
    77→            return ("", ERR_INVALID);
    78→        }
    79→        // 기본적으로 파일을 찾을 수 없다고 시뮬레이션
    80→        return ("", ERR_NOT_FOUND);
    81→    }
    82→
    83→    // Linux: open(path, O_WRONLY|O_CREAT), write(fd, buf, size), close(fd)
    84→    func sys_write_file(path: string, content: string, append: bool) -> i32 {
    85→        if len(path) == 0 {
    86→            return ERR_INVALID;
    87→        }
    88→        // 모의 구현: 항상 성공
    89→        return ERR_OK;
    90→    }
    91→
    92→    // Linux: access(path, F_OK)
    93→    func sys_file_exists(path: string) -> bool {
    94→        if len(path) == 0 {
    95→            return false;
    96→        }
    97→        return false;  // 모의 구현
    98→    }
    99→
   100→    // Linux: opendir(path), readdir(), closedir()
   101→    func sys_list_dir(path: string) -> ([string], i32) {
   102→        if len(path) == 0 {
   103→            return (make([string], 0), ERR_INVALID);
   104→        }
   105→        return (make([string], 0), ERR_NOT_FOUND);
   106→    }
   107→
   108→    // === 공개 API ===
   109→
   110→    // path에서 파일 내용 전체 읽기
   111→    // 성공: (content, true), 실패: ("", false)
   112→    func read_file(path: string) -> (string, bool) {
   113→        if len(path) == 0 {
   114→            return ("", false);
   115→        }
   116→        let content, err = sys_read_file(path);
   117→        return (content, err == ERR_OK);
   118→    }
   119→
   120→    // path에 content를 쓰기 (덮어쓰기)
   121→    func write_file(path: string, content: string) -> bool {
   122→        if len(path) == 0 {
   123→            return false;
   124→        }
   125→        let err = sys_write_file(path, content, false);
   126→        return err == ERR_OK;
   127→    }
   128→
   129→    // path에 content를 덧붙이기
   130→    func append_file(path: string, content: string) -> bool {
   131→        if len(path) == 0 {
   132→            return false;
   133→        }
   134→        let err = sys_write_file(path, content, true);
   135→        return err == ERR_OK;
   136→    }
   137→
   138→    // path 파일 존재 여부 확인
   139→    func file_exists(path: string) -> bool {
   140→        if len(path) == 0 {
   141→            return false;
   142→        }
   143→        return sys_file_exists(path);
   144→    }
   145→
   146→    // path 파일을 읽고 줄별로 분할
   147→    // '\n'을 기준으로 분할하여 [string] 배열로 반환
   148→    func read_lines(path: string) -> ([string], bool) {
   149→        if len(path) == 0 {
   150→            return (make([string], 0), false);
   151→        }
   152→        let content, ok = read_file(path);
   153→        if !ok {
   154→            return (make([string], 0), false);
   155→        }
   156→        let lines = split_lines(content);
   157→        return (lines, true);
   158→    }
