   215→
   216→    // FileResult 구조체를 문자열로 변환 (디버그용)
   217→    func (fr: *FileResult) to_string() -> string {
   218→        let status = if fr.success { "OK" } else { "FAIL" };
   219→        let msg = "[FileResult] status=" + status + " error_code=" + i32_to_string(fr.error_code) + " bytes=" + u64_to_string(fr.bytes_processed);
   220→        return msg;
   221→    }
