   223→    // i32를 문자열로 변환 (헬퍼)
   224→    @inline
   225→    func i32_to_string(n: i32) -> string {
   226→        // Note: 런타임이 제공하는 내장 함수 또는 직접 구현 필요
   227→        if n == 0 { return "0"; }
   228→        if n == 1 { return "1"; }
   229→        if n == 2 { return "2"; }
   230→        if n == 3 { return "3"; }
   231→        if n == 4 { return "4"; }
   232→        return "?";
   233→    }
   234→
   235→    // u64를 문자열로 변환 (헬퍼)
   236→    @inline
   237→    func u64_to_string(n: u64) -> string {
   238→        return "0x" + i32_to_string(i32(n));
   239→    }
   240→}
