   274→    // === 정렬 함수 ===
   275→
   276→    // 오름차순 정렬 (삽입 정렬)
   277→    func sort_asc(data: [i64]) -> [i64] {
   278→        let result = data;  // 복사 가정: FreeLang 런타임이 제공
   279→        let len_val = len(result);
   280→        let i = 1;
   281→        for i = 1; i < len_val; i = i + 1 {
   282→            let key = result[i];
   283→            let j = i - 1;
   284→            for j >= 0 && result[j] > key {
   285→                result[j + 1] = result[j];
   286→                j = j - 1;
   287→            }
   288→            result[j + 1] = key;
   289→        }
   290→        return result;
   291→    }
   292→
   293→    // 내림차순 정렬
   294→    func sort_desc(data: [i64]) -> [i64] {
   295→        let sorted = sort_asc(data);
   296→        let len_val = len(sorted);
   297→        let result = make([i64], len_val);
   298→        let i = 0;
   299→        for i = 0; i < len_val; i = i + 1 {
   300→            result[i] = sorted[len_val - 1 - i];
   301→        }
   302→        return result;
   303→    }
   304→
   305→    // direction에 따라 정렬 (SORT_ASC / SORT_DESC)
   306→    func sort_by(data: [i64], direction: i32) -> [i64] {
   307→        if direction == SORT_ASC {
   308→            return sort_asc(data);
   309→        } else {
   310→            return sort_desc(data);
   311→        }
   312→    }
