    37→// NewCluster creates a Cluster with the given replication factor.
    38→func NewCluster(rf int) *Cluster {
    39→	return &Cluster{
    40→		nodes:   make(map[string]*Node),
    41→		stores:  make(map[string]*store),
    42→		ring:    NewRing(DefaultVirtualNodes),
