    49→
    50→// AddNode registers a new node and triggers ring rebalancing + data migration.
    51→func (c *Cluster) AddNode(id, addr string) error {
    52→	c.mu.Lock()
    53→	defer c.mu.Unlock()
    54→
    55→	if _, exists := c.nodes[id]; exists {
    56→		return fmt.Errorf("node %s already exists", id)
    57→	}
    58→
    59→	// Create node and store.
    60→	node := NewNode(id, addr)
    61→	store := newStore()
    62→
    63→	c.nodes[id] = node
    64→	c.stores[id] = store
    65→
    66→	// Add to ring.
    67→	c.ring.Add(id)
    68→
    69→	// Migrate data: for each key in all other stores, check if it should live on the new node.
    70→	for nodeID, s := range c.stores {
    71→		if nodeID == id {
    72→			continue
    73→		}
    74→		keys := s.keys()
    75→		for _, key := range keys {
    76→			// Check if key now belongs to the new node.
    77→			replicas, _ := c.ring.GetN(key, c.rf)
    78→			shouldMigrate := false
    79→			for _, replica := range replicas {
    80→				if replica == id {
    81→					shouldMigrate = true
    82→					break
    83→				}
    84→			}
    85→			if shouldMigrate {
    86→				val, _ := s.get(key)
    87→				c.stores[id].set(key, val)
    88→			}
    89→		}
    90→	}
    91→
    92→	return nil
    93→}
    94→
    95→// RemoveNode deregisters a node, triggering data migration to surviving replicas.
    96→func (c *Cluster) RemoveNode(id string) error {
    97→	c.mu.Lock()
    98→	defer c.mu.Unlock()
    99→
   100→	if _, exists := c.nodes[id]; !exists {
   101→		return ErrNodeNotFound
   102→	}
   103→
   104→	// Migrate data from the removed node to surviving replicas.
   105→	if store, ok := c.stores[id]; ok {
   106→		keys := store.keys()
   107→		for _, key := range keys {
   108→			val, _ := store.get(key)
   109→			// Route to new replicas (excluding the removed node).
   110→			replicas, _ := c.ring.GetN(key, c.rf)
   111→			for _, replica := range replicas {
   112→				if replica != id {
   113→					if s, ok := c.stores[replica]; ok {
   114→						s.set(key, val)
   115→					}
   116→				}
   117→			}
   118→		}
   119→	}
   120→
   121→	// Remove from tracking structures.
   122→	delete(c.nodes, id)
   123→	delete(c.stores, id)
   124→	c.ring.Remove(id)
   125→
   126→	return nil
   127→}
   128→
   129→// Set writes value to the primary node + (rf-1) replicas.
   130→// Returns ErrNoAliveNodes if fewer than 1 replica is reachable.
   131→// Returns ErrReplicaFailure if fewer than quorum (rf/2+1) acknowledge.
   132→func (c *Cluster) Set(key, value string) error {
   133→	if key == "" {
   134→		return ErrEmptyKey
   135→	}
   136→
   137→	c.mu.RLock()
   138→	defer c.mu.RUnlock()
   139→
   140→	// Get replica nodes.
   141→	replicas, err := c.ring.GetN(key, c.rf)
   142→	if err != nil {
   143→		return err
   144→	}
   145→
   146→	// Filter to alive nodes.
   147→	alive := make([]string, 0, len(replicas))
   148→	for _, nodeID := range replicas {
   149→		if node, ok := c.nodes[nodeID]; ok && node.IsAlive() {
   150→			alive = append(alive, nodeID)
   151→		}
   152→	}
   153→
   154→	if len(alive) == 0 {
   155→		return ErrNoAliveNodes
   156→	}
   157→
   158→	// Compute quorum requirement.
   159→	quorum := c.rf/2 + 1
   160→
   161→	// Write to all alive replicas.
   162→	acks := 0
   163→	for _, nodeID := range alive {
   164→		if store, ok := c.stores[nodeID]; ok {
   165→			store.set(key, []byte(value))
   166→			acks++
   167→		}
   168→	}
   169→
   170→	if acks < quorum {
   171→		return ErrReplicaFailure
   172→	}
   173→
   174→	return nil
   175→}
   176→
   177→// Get reads from the primary node. If the primary is dead,
   178→// falls back to the next live replica.
   179→func (c *Cluster) Get(key string) (string, error) {
   180→	c.mu.RLock()
   181→	defer c.mu.RUnlock()
   182→
   183→	// Get replica nodes in order.
   184→	replicas, err := c.ring.GetN(key, c.rf)
   185→	if err != nil {
   186→		return "", err
   187→	}
   188→
   189→	// Try each replica in order until we find an alive one with the key.
   190→	for _, nodeID := range replicas {
   191→		node, ok := c.nodes[nodeID]
   192→		if !ok || !node.IsAlive() {
   193→			continue
   194→		}
   195→
   196→		store, ok := c.stores[nodeID]
   197→		if !ok {
   198→			continue
   199→		}
   200→
   201→		val, found := store.get(key)
   202→		if found {
   203→			return string(val), nil
   204→		}
   205→	}
   206→
   207→	return "", ErrKeyNotFound
   208→}
   209→
   210→// Delete removes a key from all replicas.
   211→func (c *Cluster) Delete(key string) error {
   212→	c.mu.RLock()
   213→	defer c.mu.RUnlock()
   214→
   215→	// Get replica nodes.
   216→	replicas, err := c.ring.GetN(key, c.rf)
   217→	if err != nil {
   218→		return err
   219→	}
   220→
   221→	// Delete from all replicas.
   222→	found := false
   223→	for _, nodeID := range replicas {
   224→		if store, ok := c.stores[nodeID]; ok {
   225→			if store.delete(key) {
   226→				found = true
   227→			}
   228→		}
   229→	}
   230→
   231→	if !found {
   232→		return ErrKeyNotFound
   233→	}
   234→
   235→	return nil
   236→}
   237→
   238→// NodeStatus returns the current status of a node.
   239→func (c *Cluster) NodeStatus(nodeID string) (NodeStatus, error) {
   240→	c.mu.RLock()
   241→	defer c.mu.RUnlock()
   242→
   243→	node, ok := c.nodes[nodeID]
   244→	if !ok {
   245→		return NodeAlive, ErrNodeNotFound
   246→	}
   247→
   248→	return node.Status, nil
   249→}
   250→
   251→// SimulateHeartbeat is used in tests to manually trigger heartbeat processing.
   252→func (c *Cluster) SimulateHeartbeat(nodeID string, alive bool) {
   253→	c.mu.Lock()
   254→	defer c.mu.Unlock()
   255→
   256→	node, ok := c.nodes[nodeID]
   257→	if !ok {
   258→		return
   259→	}
   260→
   261→	if alive {
   262→		node.RecordHeartbeat()
   263→		node.MarkAlive()
   264→	} else {
   265→		// Simulate missed heartbeats by setting lastHeartbeat far in the past.
   266→		node.mu.Lock()
   267→		node.lastHeartbeat = time.Now().Add(-10 * DefaultHeartbeatInterval)
   268→		node.mu.Unlock()
   269→		node.MarkDead()
   270→	}
   271→}
   272→
   273→// StartHeartbeat begins background goroutine for periodic heartbeat monitoring.
   274→func (c *Cluster) StartHeartbeat(interval time.Duration) {
   275→	c.ticker = time.NewTicker(interval)
   276→	go func() {
   277→		defer close(c.done)
   278→		for {
   279→			select {
   280→			case <-c.ticker.C:
   281→				c.processHeartbeat(interval)
   282→			case <-c.stopCh:
   283→				c.ticker.Stop()
   284→				return
   285→			}
   286→		}
   287→	}()
   288→}
   289→
   290→// processHeartbeat checks the health of all nodes and transitions states as needed.
   291→func (c *Cluster) processHeartbeat(interval time.Duration) {
   292→	c.mu.RLock()
   293→	nodes := make([]*Node, 0, len(c.nodes))
   294→	for _, node := range c.nodes {
   295→		nodes = append(nodes, node)
   296→	}
   297→	c.mu.RUnlock()
   298→
   299→	for _, node := range nodes {
   300→		age := node.HeartbeatAge()
   301→		beatThreshold := time.Duration(HeartbeatMissThreshold) * interval
   302→
   303→		if age < interval {
   304→			// Recent heartbeat, ensure Alive.
   305→			if !node.IsAlive() {
   306→				node.MarkAlive()
   307→			}
   308→		} else if age < beatThreshold {
   309→			// Missed one but not all, mark Suspect.
   310→			if node.Status == NodeAlive {
   311→				node.MarkSuspect()
   312→			}
   313→		} else {
   314→			// Missed too many, mark Dead.
   315→			node.mu.RLock()
   316→			currentStatus := node.Status
   317→			node.mu.RUnlock()
   318→
   319→			if currentStatus != NodeDead {
   320→				node.MarkDead()
   321→			}
   322→		}
   323→	}
   324→}
   325→
   326→// StopHeartbeat shuts down the heartbeat goroutine gracefully.
   327→func (c *Cluster) StopHeartbeat() {
   328→	if c.ticker != nil {
   329→		close(c.stopCh)
   330→		<-c.done
   331→	}
   332→}
   333→
   334→// Errors returns non-fatal accumulated errors.
   335→func (c *Cluster) Errors() []string {
   336→	c.mu.RLock()
   337→	defer c.mu.RUnlock()
   338→	return append([]string(nil), c.errors...)
   339→}
   340→
   341→// Stats returns a snapshot of cluster health.
   342→func (c *Cluster) Stats() ClusterStats {
   343→	c.mu.RLock()
   344→	defer c.mu.RUnlock()
   345→
   346→	alive := 0
   347→	dead := 0
   348→	for _, node := range c.nodes {
   349→		if node.IsAlive() {
   350→			alive++
   351→		} else {
   352→			dead++
   353→		}
   354→	}
   355→
   356→	totalKeys := 0
   357→	for _, s := range c.stores {
   358→		totalKeys += s.size()
   359→	}
   360→
   361→	return ClusterStats{
   362→		TotalNodes: len(c.nodes),
   363→		AliveNodes: alive,
   364→		DeadNodes:  dead,
   365→		TotalKeys:  totalKeys,
   366→	}
   367→}
   368→

