     3→import (
     4→	"encoding/binary"
     5→	"errors"
     6→	"fmt"
     7→)
     8→
     9→// Codec encodes/decodes Go values to/from []byte.
    10→// The framework ships one implementation (BinaryCodec); callers can
    11→// substitute their own (e.g., JSON for debugging).
    12→type Codec interface {
    13→	// Marshal serialises v into dst (grow as needed). Returns sub-slice used.
    14→	Marshal(v interface{}, dst []byte) ([]byte, error)
    15→	// Unmarshal deserialises src into v (v must be a pointer).
    16→	Unmarshal(src []byte, v interface{}) error
    17→}
    18→
    19→// BinaryCodec is a hand-rolled binary codec supporting common types:
    20→// string, []byte, bool, int64, nil, error.
    21→//
    22→// Type tag byte layout:
    23→//   0x01 string   4-byte len (BE) + UTF-8 bytes
    24→//   0x02 []byte   4-byte len (BE) + raw bytes
    25→//   0x03 bool     1 byte (0x00=false, 0x01=true)
    26→//   0x04 int64    8 bytes (BE)
    27→//   0x05 nil      0 additional bytes
    28→//   0x06 error    4-byte len (BE) + message bytes
    29→type BinaryCodec struct{}
    30→
    31→// NewBinaryCodec creates a new BinaryCodec.
    32→func NewBinaryCodec() *BinaryCodec {
    33→	return &BinaryCodec{}
    34→}
    35→
    36→// Marshal serialises v into dst using the binary codec.
    37→func (c *BinaryCodec) Marshal(v interface{}, dst []byte) ([]byte, error) {
    38→	if v == nil {
    39→		return append(dst, 0x05), nil
    40→	}
    41→
    42→	switch val := v.(type) {
    43→	case string:
    44→		return c.marshalString(val, dst)
    45→	case []byte:
    46→		return c.marshalBytes(val, dst)
    47→	case bool:
    48→		return c.marshalBool(val, dst)
    49→	case int64:
    50→		return c.marshalInt64(val, dst)
    51→	case error:
    52→		return c.marshalError(val, dst)
    53→	default:
    54→		return nil, fmt.Errorf("unsupported type: %T", v)
    55→	}
    56→}
    57→
    58→// Unmarshal deserialises src into v using the binary codec.
    59→func (c *BinaryCodec) Unmarshal(src []byte, v interface{}) error {
    60→	if len(src) == 0 {
    61→		return fmt.Errorf("empty buffer")
    62→	}
    63→
    64→	tag := src[0]
    65→	payload := src[1:]
    66→
    67→	switch tag {
    68→	case 0x01:
    69→		return c.unmarshalString(payload, v)
    70→	case 0x02:
    71→		return c.unmarshalBytes(payload, v)
    72→	case 0x03:
    73→		return c.unmarshalBool(payload, v)
    74→	case 0x04:
    75→		return c.unmarshalInt64(payload, v)
    76→	case 0x05:
    77→		return c.unmarshalNil(v)
    78→	case 0x06:
    79→		return c.unmarshalError(payload, v)
    80→	default:
    81→		return fmt.Errorf("unknown type tag: 0x%02x", tag)
    82→	}
    83→}
    84→
    85→func (c *BinaryCodec) marshalString(s string, dst []byte) ([]byte, error) {
    86→	dst = append(dst, 0x01)
    87→	dst = binary.BigEndian.AppendUint32(dst, uint32(len(s)))
    88→	return append(dst, []byte(s)...), nil
    89→}
    90→
    91→func (c *BinaryCodec) unmarshalString(payload []byte, v interface{}) error {
    92→	if len(payload) < 4 {
    93→		return fmt.Errorf("string payload too short")
    94→	}
    95→	length := binary.BigEndian.Uint32(payload[0:4])
    96→	if uint32(len(payload)-4) < length {
    97→		return fmt.Errorf("string length mismatch")
    98→	}
    99→
   100→	ptr, ok := v.(*string)
   101→	if !ok {
   102→		return fmt.Errorf("unmarshal string: expected *string, got %T", v)
   103→	}
   104→	*ptr = string(payload[4 : 4+length])
   105→	return nil
   106→}
   107→
   108→func (c *BinaryCodec) marshalBytes(b []byte, dst []byte) ([]byte, error) {
   109→	dst = append(dst, 0x02)
   110→	dst = binary.BigEndian.AppendUint32(dst, uint32(len(b)))
   111→	return append(dst, b...), nil
   112→}
   113→
   114→func (c *BinaryCodec) unmarshalBytes(payload []byte, v interface{}) error {
   115→	if len(payload) < 4 {
   116→		return fmt.Errorf("bytes payload too short")
   117→	}
   118→	length := binary.BigEndian.Uint32(payload[0:4])
   119→	if uint32(len(payload)-4) < length {
   120→		return fmt.Errorf("bytes length mismatch")
   121→	}
   122→
   123→	ptr, ok := v.(*[]byte)
   124→	if !ok {
   125→		return fmt.Errorf("unmarshal bytes: expected *[]byte, got %T", v)
   126→	}
   127→	*ptr = payload[4 : 4+length]
   128→	return nil
   129→}
   130→
   131→func (c *BinaryCodec) marshalBool(b bool, dst []byte) ([]byte, error) {
   132→	dst = append(dst, 0x03)
   133→	if b {
   134→		return append(dst, 0x01), nil
   135→	}
   136→	return append(dst, 0x00), nil
   137→}
   138→
   139→func (c *BinaryCodec) unmarshalBool(payload []byte, v interface{}) error {
   140→	if len(payload) < 1 {
   141→		return fmt.Errorf("bool payload too short")
   142→	}
   143→
   144→	ptr, ok := v.(*bool)
   145→	if !ok {
   146→		return fmt.Errorf("unmarshal bool: expected *bool, got %T", v)
   147→	}
   148→	*ptr = payload[0] != 0x00
   149→	return nil
   150→}
   151→
   152→func (c *BinaryCodec) marshalInt64(i int64, dst []byte) ([]byte, error) {
   153→	dst = append(dst, 0x04)
   154→	return binary.BigEndian.AppendUint64(dst, uint64(i)), nil
   155→}
   156→
   157→func (c *BinaryCodec) unmarshalInt64(payload []byte, v interface{}) error {
   158→	if len(payload) < 8 {
   159→		return fmt.Errorf("int64 payload too short")
   160→	}
   161→
   162→	ptr, ok := v.(*int64)
   163→	if !ok {
   164→		return fmt.Errorf("unmarshal int64: expected *int64, got %T", v)
   165→	}
   166→	*ptr = int64(binary.BigEndian.Uint64(payload[0:8]))
   167→	return nil
   168→}
   169→
   170→func (c *BinaryCodec) unmarshalNil(v interface{}) error {
   171→	// For nil, we expect v to be nil or an interface{} that we can't really set.
   172→	// This is mostly for symmetry. In practice, unmarshalNil is called only
   173→	// when we know the value is nil from the tag.
   174→	return nil
   175→}
   176→
   177→func (c *BinaryCodec) marshalError(err error, dst []byte) ([]byte, error) {
   178→	msg := err.Error()
   179→	dst = append(dst, 0x06)
   180→	dst = binary.BigEndian.AppendUint32(dst, uint32(len(msg)))
   181→	return append(dst, []byte(msg)...), nil
   182→}
   183→
   184→func (c *BinaryCodec) unmarshalError(payload []byte, v interface{}) error {
   185→	if len(payload) < 4 {
   186→		return fmt.Errorf("error payload too short")
   187→	}
   188→	length := binary.BigEndian.Uint32(payload[0:4])
   189→	if uint32(len(payload)-4) < length {
   190→		return fmt.Errorf("error length mismatch")
   191→	}
   192→
   193→	ptr, ok := v.(*error)
   194→	if !ok {
   195→		return fmt.Errorf("unmarshal error: expected *error, got %T", v)
   196→	}
   197→	msg := string(payload[4 : 4+length])
   198→	*ptr = errors.New(msg)
   199→	return nil
   200→}
