## 2. 핵심 설계 결정

### 설계 과제 1: 핸들러 디스패치 (함수 포인터 없이)

FreeLang에는 일급 함수가 없으므로 **switch-case 디스패치** 패턴을 사용합니다.

```
// 핸들러 ID 테이블: 최대 16개 메서드
struct HandlerTable {
    methods:   [string];    // ["kv.get", "kv.set", "ping", ...]
    count:     i32;
}

func (srv: *Server) dispatch(method: string, req: Message) -> Message {
    if method == "kv.set" {
        return handle_kv_set(req);
    }
    if method == "kv.get" {
        return handle_kv_get(req);
    }
    if method == "raft.vote" {
        return handle_raft_vote(req);
    }
    if method == "raft.append" {
        return handle_raft_append(req);
    }
    if method == "ping" {
        return handle_ping(req);
    }
    return make_error_response(req.msg_id, "method not found");
}
```

이것이 가장 FreeLang에 자연스러운 패턴입니다. json.fl의 `v.kind == KIND_NULL` 분기 패턴과 동일한 접근방식입니다.

### 설계 과제 2: 비동기-동기 변환

concurrent.fl의 Channel을 응답 채널로 사용합니다.

```
// 전역 inflight 테이블 (최대 64개 동시 요청)
let g_inflight_ids:    [i64]             // msg_id 배열
let g_inflight_chans:  [concurrent.Channel] // 응답 채널 배열
let g_inflight_count:  i32 = 0;

func rpc_call(cli: *Client, method: string, payload: i64) -> (Message, bool) {
    let msg_id = next_msg_id();
    let resp_chan = concurrent.chan_new(1);   // 용량 1: 단일 응답

    // inflight 등록
    g_inflight_ids[g_inflight_count] = msg_id;
    g_inflight_chans[g_inflight_count] = resp_chan;
    g_inflight_count = g_inflight_count + 1;

    // 요청 전송
    let req = make_request(msg_id, method, payload);
    cli.transport.send(req);

    // 응답 대기 (max 100 tick 폴링)
    let t = 0;
    for t = 0; t < 100; t = t + 1 {
        let resp_val, ok = resp_chan.chan_recv();
        if ok {
            return (decode_message(resp_val), true);
        }
    }
    return (make_null_message(), false);  // 타임아웃
}
```

### 설계 과제 3: FNV-1a 일관성 해싱 구현

```
// FNV-1a 32bit 해시 (FreeLang char_at 런타임 함수 사용)
const FNV_PRIME:    i64 = 16777619;
const FNV_OFFSET:   i64 = 2166136261;

func fnv1a_hash(key: string) -> i64 {
    let hash = FNV_OFFSET;
    let i = 0;
    let n = len(key);
    for i = 0; i < n; i = i + 1 {
        let ch = i64(char_at(key, i));
        hash = hash ^ ch;
        hash = hash * FNV_PRIME;
    }
    return hash;
}

// 가상 노드 라벨 해시: "node1#0", "node1#1", ...
func vnode_hash(node_id: string, idx: i32) -> i64 {
    let label = node_id + "#" + i32_to_str(idx);
    return fnv1a_hash(label);
}
```

### 설계 과제 4: Raft 결정론적 선거 시뮬레이션

실제 타이머가 없으므로 tick 카운터로 선거 타임아웃을 시뮬레이션합니다.

```
const ELECTION_TIMEOUT: i32 = 10;   // 10 tick
const HEARTBEAT_INTERVAL: i32 = 3;  // 3 tick

func (node: *RaftNode) raft_tick(cluster: *RaftCluster) {
    node.tick_elapsed = node.tick_elapsed + 1;

    if node.state == RAFT_FOLLOWER {
        if node.tick_elapsed >= ELECTION_TIMEOUT {
            node.become_candidate(cluster);
        }
    }
    if node.state == RAFT_CANDIDATE {
        node.try_election(cluster);
    }
    if node.state == RAFT_LEADER {
        if node.tick_elapsed % HEARTBEAT_INTERVAL == 0 {
            node.send_heartbeat(cluster);
        }
    }
}
```

