```
// 쿼럼 쓰기: 과반수(quorum개) 노드에 성공해야 성공
func (g: *ReplicaGroup) write_quorum(key: string, val: i64) -> (i32, bool) {
    let alive = g.alive_count();
    if alive == 0 {
        return (ERR_NO_ALIVE, false);
    }

    let acks = 0;
    let i = 0;
    for i = 0; i < g.node_count; i = i + 1 {
        if g.nodes[i].state == REPLICA_ALIVE {
            let ok = g.nodes[i].local_set(key, val);
            if ok {
                acks = acks + 1;
            }
        }
    }

    if acks < g.quorum {
        return (ERR_QUORUM_FAILED, false);
    }
    return (RPC_OK, true);
}

// 쿼럼 읽기: 첫 번째 alive 노드에서 읽기 (단순화)
func (g: *ReplicaGroup) read_quorum(key: string) -> (i64, bool)
