```
// tick 카운터 기반 상태 전환
func (g: *ReplicaGroup) heartbeat_check(current_tick: i32) {
    let i = 0;
    for i = 0; i < g.node_count; i = i + 1 {
        let age = current_tick - g.nodes[i].last_heartbeat;
        if age < SUSPECT_TIMEOUT {
            g.nodes[i].state = REPLICA_ALIVE;
        } else if age < HEARTBEAT_TIMEOUT {
            g.nodes[i].state = REPLICA_SUSPECT;
        } else {
            g.nodes[i].state = REPLICA_DEAD;
        }
    }
}

