```
// 후보자로 전환
func (node: *RaftNode) become_candidate(cluster: *RaftCluster) {
    node.state = RAFT_CANDIDATE;
    node.current_term = node.current_term + 1;
    node.voted_for = node.id;   // 자신에게 투표
    node.votes_received = 1;    // 자기 투표 1표
    node.tick_elapsed = 0;
    // 모든 다른 노드에 RequestVote 전송
    node.broadcast_request_vote(cluster);
}

// RequestVote RPC 처리
func (node: *RaftNode) request_vote(
    term: i32, candidate_id: i32,
    last_log_index: i32, last_log_term: i32
) -> (i32, bool) {
    // 이전 term이면 거부
    if term < node.current_term {
        return (node.current_term, false);
    }
    // term 업데이트
    if term > node.current_term {
        node.current_term = term;
        node.state = RAFT_FOLLOWER;
        node.voted_for = NONE;
    }
    // 이미 투표했으면 거부
    if node.voted_for != NONE && node.voted_for != candidate_id {
        return (node.current_term, false);
    }
    // 로그 최신성 확인
    let my_last_idx = node.log_count - 1;
    let my_last_term = if node.log_count > 0 {
        node.log[my_last_idx].term
    } else { 0 };
    if last_log_term < my_last_term {
        return (node.current_term, false);
    }
    if last_log_term == my_last_term && last_log_index < my_last_idx {
        return (node.current_term, false);
    }
    // 투표 승인
    node.voted_for = candidate_id;
    node.tick_elapsed = 0;
    return (node.current_term, true);
}

// 리더 전환
func (node: *RaftNode) become_leader(cluster: *RaftCluster) {
    node.state = RAFT_LEADER;
    // next_index 초기화
    let i = 0;
    for i = 0; i < cluster.node_count; i = i + 1 {
        node.next_index[i] = node.log_count;
        node.match_index[i] = -1;
    }
    node.send_heartbeat(cluster);
}
```

