### 3.4 stdlib/distributed.fl (~300줄)

**의존성**: rpc.fl, replication.fl, consensus.fl, concurrent.fl

이 파일은 3개 모듈을 하나의 `DistNode`로 통합하는 파사드(Facade) 레이어입니다.

**모듈 헤더 및 상수** (~20줄)
```
module distributed {
    const VNODE_COUNT:    i32 = 10;   // 가상 노드 수 (Go: 150, 시뮬레이션: 10)
    const MAX_RING_NODES: i32 = 32;   // 링 최대 물리 노드

    const FNV_PRIME:  i64 = 16777619;
    const FNV_OFFSET: i64 = 2166136261;

    const ERR_DIST_OK:       i32 = 0;
    const ERR_DIST_ROUTE:    i32 = 20;
    const ERR_DIST_QUORUM:   i32 = 21;
}
```

**구조체** (~50줄)
```
// 일관성 해시 링
struct HashRing {
    // 가상 노드 해시값 배열 (정렬됨)
    vnode_hashes:   [i64];
    // 각 가상 노드가 가리키는 물리 노드 ID
    vnode_owners:   [string];
    vnode_count:    i32;
    // 물리 노드 목록
    phys_nodes:     [string];
    phys_count:     i32;
}

// 통합 분산 노드
struct DistNode {
    id:         string;
    // RPC 레이어
    rpc_client: rpc.Client;
    rpc_server: rpc.Server;
    // 복제 레이어
    rep_group:  replication.ReplicaGroup;
    // 합의 레이어
    raft:       consensus.RaftNode;
    // 해시 링
    ring:       HashRing;
    // 통계
    total_puts: i64;
    total_gets: i64;
    total_routes: i64;
}
```

**FNV-1a 해시 및 링 관리** (~70줄)

Go의 `ring.go`를 FreeLang으로 이식합니다. Go에서는 sort로 정렬된 슬라이스를 이진 탐색하지만, FreeLang에서는 collections.fl의 `sort_asc`를 활용합니다.

```
// FNV-1a 32bit 해시
func fnv1a_hash(key: string) -> i64 {
    let hash = FNV_OFFSET;
    let i = 0;
    let n = len(key);
    for i = 0; i < n; i = i + 1 {
        let ch = i64(char_at(key, i));
        hash = (hash ^ ch) * FNV_PRIME;
    }
    // 음수 처리 (32bit 범위로 마스킹)
    if hash < 0 { hash = -hash; }
    return hash;
}

// 노드를 링에 추가 (VNODE_COUNT개 가상 노드 삽입)
func (ring: *HashRing) ring_add(node_id: string) -> bool {
    // 각 가상 노드에 대해 hash("node1#0"), hash("node1#1"), ... 계산
    let i = 0;
    for i = 0; i < VNODE_COUNT; i = i + 1 {
        let label = node_id + "#" + i32_to_str(i);
        let h = fnv1a_hash(label);
        ring.vnode_hashes[ring.vnode_count] = h;
        ring.vnode_owners[ring.vnode_count] = node_id;
        ring.vnode_count = ring.vnode_count + 1;
    }
    // 물리 노드 등록
    ring.phys_nodes[ring.phys_count] = node_id;
    ring.phys_count = ring.phys_count + 1;
    // 해시 배열을 정렬 (삽입 정렬, 작은 규모)
    ring.sort_vnodes();
    return true;
}

// 키에 대한 주 노드 반환 (이진 탐색)
func (ring: *HashRing) ring_get(key: string) -> (string, bool) {
    if ring.vnode_count == 0 {
        return ("", false);
    }
    let key_hash = fnv1a_hash(key);
    // 선형 탐색으로 첫 번째 >= key_hash 가상 노드 찾기
    // (소규모이므로 O(n)으로 충분)
    let i = 0;
    for i = 0; i < ring.vnode_count; i = i + 1 {
        if ring.vnode_hashes[i] >= key_hash {
            return (ring.vnode_owners[i], true);
        }
    }
    // 링 wrap-around: 첫 번째 가상 노드
    return (ring.vnode_owners[0], true);
}

// 노드 제거
func (ring: *HashRing) ring_remove(node_id: string)

// 내부 정렬 (삽입 정렬)
func (ring: *HashRing) sort_vnodes()
```

**통합 API** (~80줄)
```
// DistNode 생성
func dist_new(id: string, cluster_size: i32) -> DistNode

// 클러스터에 노드 추가
func (d: *DistNode) dist_add_peer(peer_id: string, peer_addr: string) -> bool

// 라우팅 기반 쓰기
func (d: *DistNode) dist_put(key: string, val: i64) -> (i32, bool) {
    // 1. 해시 링으로 담당 노드 결정
    let target, ok = d.ring.ring_get(key);
    if !ok { return (ERR_DIST_ROUTE, false); }
    d.total_routes = d.total_routes + 1;

    // 2. 현재 노드가 담당이면 직접 복제 그룹에 쓰기
    if target == d.id {
        let err, ok2 = d.rep_group.write_quorum(key, val);
        d.total_puts = d.total_puts + 1;
        return (err, ok2);
    }

    // 3. 원격 노드면 RPC로 전달 (시뮬레이션: 직접 찾아서 write)
    return d.remote_put(target, key, val);
}

// 라우팅 기반 읽기
func (d: *DistNode) dist_get(key: string) -> (i64, bool) {
    let target, ok = d.ring.ring_get(key);
    if !ok { return (0, false); }
    d.total_gets = d.total_gets + 1;

    if target == d.id {
        return d.rep_group.read_quorum(key);
    }
    return d.remote_get(target, key);
}

// 라우팅 정보 반환 (디버그용)
func (d: *DistNode) dist_route(key: string) -> string

// 통계 출력
func (d: *DistNode) dist_stats() -> string
```

**원격 통신 시뮬레이션** (~40줄)

실제 네트워크 없이 전역 클러스터 레지스트리로 "원격" 노드를 직접 참조합니다.

```
// 전역 클러스터 레지스트리 (테스트 시뮬레이션용)
let g_cluster_nodes:  [*DistNode];
let g_cluster_count:  i32 = 0;

func dist_register(d: *DistNode)
func dist_find_node(id: string) -> (*DistNode, bool)

func (d: *DistNode) remote_put(target: string, key: string, val: i64) -> (i32, bool) {
    let node, ok = dist_find_node(target);
    if !ok { return (ERR_DIST_ROUTE, false); }
    return node.rep_group.write_quorum(key, val);
}

func (d: *DistNode) remote_get(target: string, key: string) -> (i64, bool) {
    let node, ok = dist_find_node(target);
    if !ok { return (0, false); }
    return node.rep_group.read_quorum(key);
}
```

