**테스트 시나리오 2: 복제 쿼럼** (~45줄)
```
func test_replication() {
    print("\n=== Replication Tests ===");

    // 3노드 그룹 생성
    let group = replication.group_new(2, 3);
    let n1 = replication.replica_node_new("node1", "localhost:8001");
    let n2 = replication.replica_node_new("node2", "localhost:8002");
    let n3 = replication.replica_node_new("node3", "localhost:8003");
    group.node_add(n1);
    group.node_add(n2);
    group.node_add(n3);

    // 쿼럼 쓰기 성공 (3개 alive)
    let err, ok = group.write_quorum("key1", 100);
    let r1 = assert_true(ok, "write_quorum 3/3 nodes alive");
    print_result(r1);

    // 노드 하나를 DEAD로 설정 (쿼럼 여전히 통과: 2/3)
    group.nodes[2].state = replication.REPLICA_DEAD;
    let err2, ok2 = group.write_quorum("key2", 200);
    let r2 = assert_true(ok2, "write_quorum 2/3 nodes alive (quorum met)");
    print_result(r2);

    // 두 노드 DEAD (쿼럼 실패: 1/3)
    group.nodes[1].state = replication.REPLICA_DEAD;
    let err3, ok3 = group.write_quorum("key3", 300);
    let r3 = assert_true(!ok3, "write_quorum 1/3 nodes alive (quorum failed)");
    print_result(r3);

    // 읽기 테스트
    group.nodes[1].state = replication.REPLICA_ALIVE;
    group.nodes[2].state = replication.REPLICA_ALIVE;
    let val, ok4 = group.read_quorum("key1");
    let r4 = assert_eq_i64(val, 100, "read_quorum key1");
    print_result(r4);
}
