func test_raft() {
    print("\n=== Raft Consensus Tests ===");

    // 3노드 클러스터 생성
    let cluster = consensus.raft_cluster_new(3);

    // 초기 상태: 모두 FOLLOWER
    let r1 = assert_true(cluster.nodes[0].state == consensus.RAFT_FOLLOWER, "initial state follower");
    print_result(r1);

    // ELECTION_TIMEOUT tick 진행 → 첫 번째 노드 후보로 전환
    let t = 0;
    for t = 0; t < consensus.ELECTION_TIMEOUT + 1; t = t + 1 {
        cluster.tick_all();
    }

    // 누군가 리더로 선출되었는지 확인
    let leader_id, ok = cluster.nodes[0].find_leader(&cluster);
    let r2 = assert_true(ok, "leader elected after timeout");
    print_result(r2);

    // 리더에게 로그 항목 추가
    if ok {
        let leader_idx = leader_id;
        let log_idx = cluster.nodes[leader_idx].log_append(
            consensus.CMD_SET, "testkey", 999
        );
        let r3 = assert_true(log_idx >= 0, "log append to leader");
        print_result(r3);

        // 추가 tick으로 복제 완료
        for t = 0; t < 5; t = t + 1 {
            cluster.tick_all();
        }
    }
}
