let g_next_msg_id: i64 = 1;          // 단조 증가 메시지 ID
let g_msg_pool:    [Message];         // 메시지 객체 풀 (최대 256개)
let g_msg_pool_count: i32 = 0;

// distributed.fl
let g_dist_nodes:  [string];          // 등록된 노드 ID 목록
let g_dist_count:  i32 = 0;
// 실제 노드 참조는 포인터 배열로 (또는 인덱스 기반 접근)
```

